INSERT INTO collection_pages VALUES('c9809919e45146ca28ddeba71681e36096d9720f4c92cac552c62242ff4a7c94','55131bf0decd88052f7c32709a6d362dde191b9fba0da4aa2c4e78b15e85ec0d','{"hasNext":false,"items":[{"author":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"authoredDate":"2025-11-17T10:24:44Z","committedDate":"2025-11-17T10:24:44Z","committer":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"observedAt":"2026-10-08T20:56:14.462Z","repositoryId":1098148530,"sha":"6e2579edce9301893a5105d25716552836381b26"}],"observedAt":"2026-10-08T20:56:14.462Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/doandat/RNRePackModuleFederations/commits/6e2579edce9301893a5105d25716552836381b26/comments","commit":{"author":{"date":"2025-11-17T10:24:44Z","email":"noreply@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2025-11-17T10:24:44Z","email":"noreply@anthropic.com","name":"Claude"},"message":"feat: Initial React Native Re.Pack project with Firebase Authentication\n\nThis commit sets up a complete React Native sample project demonstrating\nthe integration of Re.Pack (Webpack-based bundler) with Firebase Authentication.\n\nFeatures:\n- React Native 0.73.2 with TypeScript support\n- Re.Pack 4.1.0 webpack configuration\n- Firebase Authentication (@react-native-firebase/auth)\n- Email/password authentication flow\n- User registration with validation\n- Login screen with error handling\n- Authenticated home screen with user info\n- React Navigation with auth-based routing\n- Android and iOS native configurations\n- Comprehensive documentation and setup guides\n\nProject Structure:\n- src/screens/: Authentication screens (Login, Register, Home)\n- src/App.tsx: Root component with auth state management\n- webpack.config.mjs: Re.Pack webpack configuration\n- android/: Android native code and configuration\n- ios/: iOS native code and configuration\n\nDocumentation:\n- README.md: Project overview and features\n- SETUP_GUIDE.md: Step-by-step setup instructions\n- ARCHITECTURE.md: Detailed architecture documentation\n- CHANGELOG.md: Version history\n\nThe project is ready for development after:\n1. Running npm install\n2. Adding Firebase configuration files\n3. Installing iOS pods\n4. Running on Android/iOS","tree":{"sha":"89e22e32e471c9857a3aae1e2cb23d32b4b9a18f","url":"https://api.github.com/repos/doandat/RNRePackModuleFederations/git/trees/89e22e32e471c9857a3aae1e2cb23d32b4b9a18f"},"url":"https://api.github.com/repos/doandat/RNRePackModuleFederations/git/commits/6e2579edce9301893a5105d25716552836381b26","verification":{"payload":"tree 89e22e32e471c9857a3aae1e2cb23d32b4b9a18f\nauthor Claude <noreply@anthropic.com> 1763375084 +0000\ncommitter Claude <noreply@anthropic.com> 1763375084 +0000\n\nfeat: Initial React Native Re.Pack project with Firebase Authentication\n\nThis commit sets up a complete React Native sample project demonstrating\nthe integration of Re.Pack (Webpack-based bundler) with Firebase Authentication.\n\nFeatures:\n- React Native 0.73.2 with TypeScript support\n- Re.Pack 4.1.0 webpack configuration\n- Firebase Authentication (@react-native-firebase/auth)\n- Email/password authentication flow\n- User registration with validation\n- Login screen with error handling\n- Authenticated home screen with user info\n- React Navigation with auth-based routing\n- Android and iOS native configurations\n- Comprehensive documentation and setup guides\n\nProject Structure:\n- src/screens/: Authentication screens (Login, Register, Home)\n- src/App.tsx: Root component with auth state management\n- webpack.config.mjs: Re.Pack webpack configuration\n- android/: Android native code and configuration\n- ios/: iOS native code and configuration\n\nDocumentation:\n- README.md: Project overview and features\n- SETUP_GUIDE.md: Step-by-step setup instructions\n- ARCHITECTURE.md: Detailed architecture documentation\n- CHANGELOG.md: Version history\n\nThe project is ready for development after:\n1. Running npm install\n2. Adding Firebase configuration files\n3. Installing iOS pods\n4. Running on Android/iOS\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgrLzsfFISF4by8Q+FKz27YpkK1USsBB+m\namu1QkJnbDsAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5AAAAQIY8PP84\nZtObMk7HzOwC4fTpW0BhZgz0ORTJrY8AbQ1HcZAdyZ1jAxjznp5ck/DFAz6wbyaFK1HDnxSlYEtJ\nVgs=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2025-11-17T10:24:55Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs"